```jsx
import { View, Text, Button, StyleSheet } from 'react-native';
import RouteMap from '../../components/RouteMap';
import { useDriverLocation } from '../../hooks/useDriverLocation';

export default function HomeScreen() {
  const { driver } = useSession();
  const isAvailable = driver?.isAvailable ?? false;

  const { coords, permissionStatus, canAskAgain, openSettings, retryPermissions } =
    useDriverLocation({
      driverId: driver?.id,
      isAvailable,
    });

  // Manejo de pantallas de bloqueo por permisos/GPS
  if (permissionStatus === 'disabled') {
    return (
      <View style={styles.center}>
        <Text>El GPS de tu teléfono está apagado.</Text>
        <Button title="Abrir Ajustes" onPress={openSettings} />
      </View>
    );
  }

  if (permissionStatus === 'denied') {
    return (
      <View style={styles.center}>
        <Text>Se requiere permiso de ubicación para operar.</Text>
        {canAskAgain ? (
          <Button title="Dar Permiso" onPress={retryPermissions} />
        ) : (
          <Button title="Abrir Ajustes de la App" onPress={openSettings} />
        )}
      </View>
    );
  }

  return (
    <View style={styles.container}>
      <RouteMap
        center={coords}
        markers={
          coords
            ? [{ id: 'driver', latitude: coords.latitude, longitude: coords.longitude, label: 'Tú' }]
            : []
        }
      />
      {/* Aquí va el switch o botón de "Ponerse Disponible" */}
    </View>
  );
}
```

